            ok: finalHttpStatusCode < 400,
            overall_status: finalHttpStatusCode < 400 ? "OK" : "Error",
            final_http_status_code: finalHttpStatusCode
        }
    };
}

msg.statusCode = finalHttpStatusCode;
msg.payload = response;

if (msg.res) {
    return [msg, null];
}
return [null, msg];
